class MstatusBundle extends CSRBundle {
  val SIE  = CSRRWField     (1).withReset(0.U)
  val SDT  = CSRRWField     (24).withReset(0.U)  // Ssdbltrp (ratified)
  val MDT  = CSRRWField     (42).withReset(mdtInit.U)  // Smdbltrp (ratified)
  // No MIPU/SIPU bits defined anywhere
}

class SstatusBundle extends CSRBundle {
  val SDT  = CSRWARLField   (24, wNoFilter).withReset(0.U)  // Ssdbltrp only
  // No SIPU bit defined
}

class Mstateen0Bundle extends Hstateen0Bundle {
  val AIA     = RW(59).withReset(0.U)   // ratified AIA
  val IMSIC   = RW(58).withReset(0.U)   // ratified IMSIC
  // No CLIC/Smip state enable bits
}
